// AI Agent Tool: read_file
const filePath = $input.item.json.filePath;

// Get repo context from input
const owner = $input.item.json.owner;
const repo = $input.item.json.repo;
const branch = $input.item.json.branch || 'main';

if (!owner || !repo || !filePath) {
  return {
    json: {
      success: false,
      error: 'Missing required parameters. Need: owner, repo, filePath. Got: ' + JSON.stringify({ owner, repo, filePath })
    }
  };
}

// Build GitHub file URL
const url = `https://api.github.com/repos/${owner}/${repo}/contents/${filePath}?ref=${branch}`;

try {
  // Fetch file contents
  const response = await fetch(url, {
    headers: {
      'Authorization': `Bearer ${$env.GITHUB_TOKEN}`,
      'Accept': 'application/vnd.github.raw',
      'X-GitHub-Api-Version': '2022-11-28'
    }
  });

  if (!response.ok) {
    throw new Error(`GitHub API returned ${response.status}: ${response.statusText}`);
  }

  const content = await response.text();

  // Add line numbers
  const lines = content.split('\n');
  const numberedContent = lines.map((line, i) => `${i + 1}\t${line}`).join('\n');

  return {
    json: {
      success: true,
      filePath: filePath,
      content: numberedContent,
      rawContent: content,
      lines: lines.length,
      size: content.length,
      message: `Successfully read ${filePath} (${lines.length} lines, ${content.length} bytes)`
    }
  };
} catch (error) {
  return {
    json: {
      success: false,
      error: 'Failed to read file: ' + error.message,
      filePath: filePath,
      url: url
    }
  };
}
